INSERT INTO "Pais" ("ID", "nombre", "descripcion", "imagen", "codigo", "gmt") VALUES
(8, 'Corea del Sur', 'País asiático destacado por su tecnología, cultura pop y desarrollo económico.', 'https://images.pexels.com/photos/237211/pexels-photo-237211.jpeg', 'KR', '9.00'),
(10, 'Italia', 'País europeo conocido por su historia, arquitectura y gastronomía.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1600&h=900&q=80', 'IT', '1.00'),
(11, 'España', 'País europeo famoso por su cultura, turismo y tradiciones históricas.', 'https://images.unsplash.com/photo-1543783207-ec64e4d95325?auto=format&fit=crop&w=1600&h=900&q=80', 'ES', '1.00'),
(12, 'Chile', 'País sudamericano conocido por su geografía extensa y diversidad natural.', 'https://images.unsplash.com/photo-1516306580123-e6e52b1b7b5f?auto=format&fit=crop&w=1600&h=900&q=80', 'CL', '-4.00'),
(1, 'Argentina', 'País ubicado en Sudamérica, reconocido por su cultura, fútbol y gastronomía.', 'https://images.unsplash.com/photo-1589909202802-8f4aadce1849?auto=format&fit=crop&w=1600&h=900&q=80', 'AR', '-3.00'),
(2, 'Australia', 'País y continente conocido por su biodiversidad, playas y ciudades modernas.', 'https://images.unsplash.com/photo-1523482580672-f109ba8cb9be?auto=format&fit=crop&w=1600&h=900&q=80', 'AU', '10.00'),
(3, 'Estados Unidos', 'País de América del Norte con gran influencia económica, tecnológica y cultural.', 'https://images.unsplash.com/photo-1485738422979-f5c462d49f74?auto=format&fit=crop&w=1600&h=900&q=80', 'US', '-5.00'),
(4, 'Brasil', 'País sudamericano famoso por el carnaval, el fútbol y la selva amazónica.', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?auto=format&fit=crop&w=1600&h=900&q=80', 'BR', '-3.00'),
(5, 'Inglaterra', 'Nación del Reino Unido reconocida por Londres, su historia y la monarquía.', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1600&h=900&q=80', 'GB', '0.00'),
(6, 'Francia', 'País europeo conocido por París, la moda, el arte y la gastronomía.', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1600&h=900&q=80', 'FR', '1.00'),
(7, 'Israel', 'País de Medio Oriente con gran importancia histórica, cultural y tecnológica.', 'https://images.unsplash.com/photo-1542744173-8e7e53415bb0?auto=format&fit=crop&w=1600&h=900&q=80', 'IL', '2.00'),
(9, 'China', 'País asiático con una de las civilizaciones más antiguas y gran potencia mundial.', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?auto=format&fit=crop&w=1600&h=900&q=80', 'CN', '8.00');
INSERT INTO "DocumentacionPais" ("IDPais", "documentacion") VALUES
('1', 'Para viajar a Argentina se debe contar con un documento de viaje vigente y verificar los requisitos de ingreso según la nacionalidad. La permanencia autorizada, la necesidad de visa, los requisitos sanitarios y las condiciones para menores deben confirmarse en los sitios oficiales de Migraciones y de la representación diplomática argentina. Se recomienda conservar copias del pasaporte, seguro de viaje, reservas y datos de contacto de emergencia.'),
('2', 'Antes de viajar a Australia se debe solicitar la autorización o visa correspondiente y presentar un pasaporte vigente. Australia aplica controles estrictos de bioseguridad: deben declararse alimentos, medicamentos, plantas, semillas, productos animales y efectivo según corresponda. Los requisitos migratorios, sanitarios y de tránsito deben confirmarse en Home Affairs y en la embajada correspondiente.'),
('3', 'El ingreso a Estados Unidos depende de la nacionalidad y del propósito del viaje. Es necesario contar con pasaporte vigente y, según el caso, autorización ESTA o visa. La autorización electrónica no garantiza el ingreso: la decisión final corresponde al control fronterizo. Se deben declarar alimentos, productos agrícolas, medicamentos y otros artículos regulados.'),
('4', 'Para ingresar a Brasil se requiere un documento de viaje válido y, para algunas nacionalidades, una visa o autorización previa. Se deben revisar los requisitos migratorios, sanitarios y de vacunación vigentes en los canales oficiales. Los menores pueden necesitar autorización adicional para viajar. Se recomienda guardar comprobantes de alojamiento, pasaje de salida y seguro de viaje.'),
('5', 'El ingreso a Inglaterra se rige por las normas del Reino Unido. Se debe viajar con pasaporte vigente y comprobar si corresponde visa o autorización electrónica según la nacionalidad y el motivo del viaje. La duración autorizada y las condiciones de entrada deben verificarse en GOV.UK antes de comprar el pasaje.'),
('6', 'Para viajar a Francia se deben cumplir las condiciones del espacio Schengen y los requisitos específicos de la nacionalidad. Es necesario verificar pasaporte, visa o autorización previa, seguro y comprobantes del motivo del viaje cuando correspondan. Los documentos exigidos pueden cambiar, por lo que deben consultarse en France-Visas y en la representación consular.'),
('7', 'Los requisitos de entrada a Israel dependen de la nacionalidad, el motivo del viaje y la situación vigente. Se debe viajar con pasaporte válido y verificar visa, autorización electrónica, seguro y requisitos sanitarios antes de partir. Las autoridades pueden realizar controles adicionales y determinar el período autorizado de permanencia.'),
('8', 'El ingreso a Corea del Sur requiere pasaporte vigente y, según la nacionalidad, visa o autorización electrónica. Se deben confirmar los requisitos de inmigración, aduana y salud en los sitios oficiales antes del viaje. Algunos medicamentos y productos alimenticios están sujetos a declaración o restricciones.'),
('9', 'Para ingresar a China se necesita pasaporte vigente y, en la mayoría de los casos, visa según el motivo del viaje. Deben revisarse las condiciones de tránsito, registro de alojamiento, requisitos sanitarios y declaraciones aduaneras vigentes. La documentación y las reglas pueden variar por región y cambiar con frecuencia.'),
('10', 'El ingreso a Italia se encuentra sujeto a las reglas del espacio Schengen y a la nacionalidad del viajero. Se deben verificar pasaporte, visa o autorización previa, seguro y documentación del alojamiento. Para estancias prolongadas pueden existir obligaciones de registro o permisos adicionales.'),
('11', 'El ingreso a España se rige por la normativa española y del espacio Schengen. Se debe confirmar la validez del pasaporte, la necesidad de visa o autorización electrónica y los requisitos de estancia según la nacionalidad. Se recomienda disponer de seguro, alojamiento y prueba de salida cuando sean exigibles.'),
('12', 'Para ingresar a Chile se requiere un documento de viaje vigente y, según la nacionalidad, visa o autorización previa. Se deben confirmar los requisitos migratorios, sanitarios y aduaneros en los canales oficiales. La entrada de alimentos, semillas, productos animales y vegetales está controlada y debe declararse.');
INSERT INTO "PaisDocumentacion" ("IDPais", "nombre", "codigo", "descripcion", "imagen", "documentacion", "reglas", "vidaDiaria") VALUES
('1', 'Argentina', 'AR', 'País de América del Sur con gran diversidad geográfica y cultural.', 'https://flagcdn.com/w320/ar.png', 'Para viajar a Argentina se debe contar con un documento de viaje vigente y verificar los requisitos de ingreso según la nacionalidad. La permanencia autorizada, la necesidad de visa, los requisitos sanitarios y las condiciones para menores deben confirmarse en los sitios oficiales de Migraciones y de la representación diplomática argentina. Se recomienda conservar copias del pasaporte, seguro de viaje, reservas y datos de contacto de emergencia.', 'Respetar las leyes argentinas, las normas aduaneras y las indicaciones de las autoridades. No transportar sustancias, armas, alimentos o medicamentos restringidos sin autorización. Para conducir se necesita licencia válida y se deben respetar los límites de velocidad, el uso del cinturón y las normas de tránsito. En áreas naturales está prohibido extraer flora, fauna o patrimonio.', '• Transporte público irregular o con demoras en algunas zonas.
INSERT INTO "PaisInfo" ("ID", "IDPais", "requisitosVisa", "vacunasObligatorias", "vacunasRecomendadas", "notasGenerales", "reglas", "vidaDiaria", "documentacion") VALUES
(7, 7, 'Sin visa hasta 90 días.', 'Ninguna', 'Hepatitis A y B', 'Controles migratorios estrictos. Seguro recomendado.', 'Cumplir las indicaciones de seguridad y las normas de las autoridades locales. Algunas zonas pueden tener restricciones de acceso o cambios de circulación. Respetar lugares religiosos, horarios de descanso y normas de vestimenta. No fotografiar instalaciones sensibles ni ingresar a áreas restringidas.', 'La moneda es el nuevo séquel israelí. Los horarios y servicios pueden modificarse durante Shabat y festividades religiosas. Se recomienda comprobar transporte, aperturas y alertas de seguridad antes de cada desplazamiento, contratar seguro y llevar siempre un documento de identidad.', 'Los requisitos de entrada a Israel dependen de la nacionalidad, el motivo del viaje y la situación vigente. Se debe viajar con pasaporte válido y verificar visa, autorización electrónica, seguro y requisitos sanitarios antes de partir. Las autoridades pueden realizar controles adicionales y determinar el período autorizado de permanencia.'),
(1, 1, 'No aplica', 'Ninguna', 'Calendario nacional al día', 'DNI o pasaporte válido.', 'Respetar las leyes argentinas, las normas aduaneras y las indicaciones de las autoridades. No transportar sustancias, armas, alimentos o medicamentos restringidos sin autorización. Para conducir se necesita licencia válida y se deben respetar los límites de velocidad, el uso del cinturón y las normas de tránsito. En áreas naturales está prohibido extraer flora, fauna o patrimonio.', 'La moneda oficial es el peso argentino. Los horarios comerciales, medios de pago y cobertura móvil pueden variar entre ciudades. En zonas turísticas conviene utilizar transporte y servicios habilitados, cuidar los objetos personales y contratar asistencia médica. Los números de emergencia son 911 para emergencias generales, 100 para bomberos y 107 para emergencias médicas en muchas jurisdicciones.', 'Para viajar a Argentina se debe contar con un documento de viaje vigente y verificar los requisitos de ingreso según la nacionalidad. La permanencia autorizada, la necesidad de visa, los requisitos sanitarios y las condiciones para menores deben confirmarse en los sitios oficiales de Migraciones y de la representación diplomática argentina. Se recomienda conservar copias del pasaporte, seguro de viaje, reservas y datos de contacto de emergencia.'),
(8, 8, 'Sin visa para turismo corto. Puede requerir autorización electrónica según normativa vigente.', 'Ninguna', 'Hepatitis A y B', 'Pasaporte vigente y pasaje de salida.', 'Respetar las leyes de la República de Corea, las normas de transporte y las indicaciones de seguridad. No ingresar sustancias controladas ni realizar actividades laborales sin autorización migratoria. En templos, palacios y áreas naturales se deben respetar las reglas de conservación y comportamiento.', 'La moneda es el won surcoreano. El transporte público es amplio y utiliza tarjetas o sistemas de pago locales. Se recomienda llevar la dirección del alojamiento en coreano, utilizar aplicaciones oficiales de transporte y tener en cuenta que algunas zonas pueden presentar barreras idiomáticas.', 'El ingreso a Corea del Sur requiere pasaporte vigente y, según la nacionalidad, visa o autorización electrónica. Se deben confirmar los requisitos de inmigración, aduana y salud en los sitios oficiales antes del viaje. Algunos medicamentos y productos alimenticios están sujetos a declaración o restricciones.'),
(2, 2, 'eVisitor / ETA electrónica previa. Estadías cortas de turismo.', 'Ninguna', 'Hepatitis A y B, antigripal', 'Pasaporte vigente. Seguro médico recomendado.', 'Cumplir las normas de bioseguridad, aduana y conservación ambiental. Está prohibido introducir productos no declarados y se aplican sanciones por conducir bajo los efectos del alcohol o incumplir las normas viales. En las playas y parques se deben seguir las señales, respetar zonas protegidas y no acercarse a fauna silvestre.', 'La moneda es el dólar australiano y se utilizan tarjetas ampliamente, aunque conviene disponer de un medio alternativo. Se conduce por la izquierda. Las distancias son grandes y algunas zonas tienen poca cobertura móvil; se recomienda planificar combustible, agua, alojamiento y asistencia médica antes de realizar recorridos alejados.', 'Antes de viajar a Australia se debe solicitar la autorización o visa correspondiente y presentar un pasaporte vigente. Australia aplica controles estrictos de bioseguridad: deben declararse alimentos, medicamentos, plantas, semillas, productos animales y efectivo según corresponda. Los requisitos migratorios, sanitarios y de tránsito deben confirmarse en Home Affairs y en la embajada correspondiente.'),
(3, 3, 'ESTA obligatoria (si cumple condiciones) o visa B1/B2. Hasta 90 días con ESTA.', 'Ninguna', 'Hepatitis A y B, antigripal', 'Pasaporte electrónico vigente. Seguro médico muy recomendable.', 'Cumplir las leyes federales, estatales y locales, que pueden variar entre estados. Respetar las normas de tránsito, las restricciones de parques nacionales y las indicaciones de seguridad. Las armas, sustancias controladas y ciertos medicamentos están sujetos a controles estrictos. No trabajar ni estudiar con una categoría migratoria que no lo permita.', 'La moneda es el dólar estadounidense. Los impuestos normalmente se agregan al precio publicado y en restaurantes se acostumbra dejar propina por el servicio. Se conduce por la derecha y las distancias pueden ser extensas. El 911 atiende emergencias de policía, bomberos y ambulancia.', 'El ingreso a Estados Unidos depende de la nacionalidad y del propósito del viaje. Es necesario contar con pasaporte vigente y, según el caso, autorización ESTA o visa. La autorización electrónica no garantiza el ingreso: la decisión final corresponde al control fronterizo. Se deben declarar alimentos, productos agrícolas, medicamentos y otros artículos regulados.'),
(4, 4, 'Sin visa. Hasta 90 días.', 'Ninguna (salvo casos especiales por fiebre amarilla)', 'Fiebre amarilla, Hepatitis A', 'Puede ingresar con DNI o pasaporte.', 'Respetar las leyes federales y estatales, la normativa aduanera y las áreas ambientales protegidas. No extraer especies, introducir productos biológicos sin declarar ni conducir sin licencia válida. En playas, ríos y parques se deben seguir las instrucciones locales y evitar zonas señalizadas como peligrosas.', 'La moneda es el real brasileño. El portugués es el idioma oficial y las tarjetas son aceptadas en la mayoría de las ciudades, aunque puede ser útil llevar efectivo. En destinos grandes se recomienda utilizar transporte autorizado, cuidar pertenencias y verificar las condiciones climáticas antes de desplazarse.', 'Para ingresar a Brasil se requiere un documento de viaje válido y, para algunas nacionalidades, una visa o autorización previa. Se deben revisar los requisitos migratorios, sanitarios y de vacunación vigentes en los canales oficiales. Los menores pueden necesitar autorización adicional para viajar. Se recomienda guardar comprobantes de alojamiento, pasaje de salida y seguro de viaje.'),
(5, 5, 'ETA obligatoria antes de viajar. Hasta 6 meses de turismo.', 'Ninguna', 'Hepatitis A y B, antigripal', 'Pasaporte obligatorio.', 'Respetar la legislación del Reino Unido y las normas locales. Se conduce por la izquierda y existen zonas de circulación restringida en algunas ciudades. No transportar artículos prohibidos, alimentos restringidos o medicamentos sin la documentación correspondiente. En edificios históricos, parques y museos se deben seguir las reglas de conservación.', 'La moneda es la libra esterlina. El clima es variable y suele llover, por lo que conviene llevar ropa adecuada. El transporte público utiliza horarios y tarifas específicos; se recomienda consultar operadores oficiales. El número general de emergencias es 999 y también puede utilizarse 112.', 'El ingreso a Inglaterra se rige por las normas del Reino Unido. Se debe viajar con pasaporte vigente y comprobar si corresponde visa o autorización electrónica según la nacionalidad y el motivo del viaje. La duración autorizada y las condiciones de entrada deben verificarse en GOV.UK antes de comprar el pasaje.'),
(6, 6, 'Sin visa hasta 90 días. ETIAS previsto para fines de 2026.', 'Ninguna', 'Hepatitis A y B, antigripal', 'Pasaporte válido, fondos y alojamiento demostrables.', 'Respetar las leyes francesas, las normas de seguridad y las reglas de los espacios culturales y naturales. Los documentos personales pueden ser solicitados por las autoridades. Para conducir se requiere licencia válida y seguro. No introducir productos restringidos ni retirar piezas de patrimonio o especies protegidas.', 'La moneda es el euro. En ciudades y zonas turísticas hay amplia disponibilidad de transporte público, pero las huelgas o cambios de servicio pueden afectar los horarios. Se recomienda validar los billetes, cuidar los objetos personales y conservar la documentación durante toda la estancia.', 'Para viajar a Francia se deben cumplir las condiciones del espacio Schengen y los requisitos específicos de la nacionalidad. Es necesario verificar pasaporte, visa o autorización previa, seguro y comprobantes del motivo del viaje cuando correspondan. Los documentos exigidos pueden cambiar, por lo que deben consultarse en France-Visas y en la representación consular.'),
(9, 9, 'Exención de visa para turismo de corta duración (según acuerdos vigentes).', 'Ninguna', 'Hepatitis A y B', 'Pasaporte con vigencia mínima recomendada de 6 meses.', 'Cumplir las leyes nacionales y locales, las normas de seguridad y las restricciones de acceso a instalaciones o zonas protegidas. No transportar artículos prohibidos, fotografiar lugares restringidos ni realizar actividades profesionales sin autorización. Respetar los controles aduaneros y conservar los documentos de viaje.', 'La moneda es el yuan o renminbi. Muchos servicios utilizan aplicaciones y medios de pago locales; conviene prepararlos con anticipación. La disponibilidad de internet, tarjetas extranjeras y aplicaciones internacionales puede variar. Se recomienda contar con traducciones del alojamiento y un contacto local de emergencia.', 'Para ingresar a China se necesita pasaporte vigente y, en la mayoría de los casos, visa según el motivo del viaje. Deben revisarse las condiciones de tránsito, registro de alojamiento, requisitos sanitarios y declaraciones aduaneras vigentes. La documentación y las reglas pueden variar por región y cambiar con frecuencia.'),
(10, 10, 'Sin visa hasta 90 días. ETIAS previsto para fines de 2026.', 'Ninguna', 'Hepatitis A y B, antigripal', 'Espacio Schengen. Pasaporte vigente.', 'Respetar las leyes italianas, las normas de circulación y las reglas de museos, iglesias, sitios arqueológicos y áreas protegidas. No retirar piezas históricas ni ingresar a monumentos fuera de las zonas habilitadas. Para conducir se requiere licencia y seguro válidos.', 'La moneda es el euro. En ciudades turísticas se recomienda reservar entradas y transporte con operadores oficiales. Los horarios comerciales y de transporte pueden cambiar según la localidad y la temporada. Se debe validar el billete de transporte y cuidar las pertenencias en lugares concurridos.', 'El ingreso a Italia se encuentra sujeto a las reglas del espacio Schengen y a la nacionalidad del viajero. Se deben verificar pasaporte, visa o autorización previa, seguro y documentación del alojamiento. Para estancias prolongadas pueden existir obligaciones de registro o permisos adicionales.'),
(11, 11, 'Sin visa hasta 90 días. ETIAS previsto para fines de 2026.', 'Ninguna', 'Hepatitis A y B, antigripal', 'Espacio Schengen. Puede solicitar prueba de alojamiento y fondos.', 'Cumplir las leyes nacionales y autonómicas, las normas de tránsito y las reglas de playas, parques y monumentos. No conducir bajo los efectos del alcohol, transportar productos restringidos ni retirar patrimonio. En alojamientos puede solicitarse el registro de los datos del viajero.', 'La moneda es el euro. Los horarios de comidas y comercios pueden ser diferentes a los del país de origen. Se recomienda utilizar transporte autorizado, validar billetes y reservar con anticipación en temporada alta. El 112 es el número europeo de emergencias.', 'El ingreso a España se rige por la normativa española y del espacio Schengen. Se debe confirmar la validez del pasaporte, la necesidad de visa o autorización electrónica y los requisitos de estancia según la nacionalidad. Se recomienda disponer de seguro, alojamiento y prueba de salida cuando sean exigibles.'),
(12, 12, 'Sin visa. Hasta 90 días.', 'Ninguna', 'Hepatitis A y B', 'Puede ingresar con DNI o pasaporte.', 'Respetar las leyes chilenas, las normas de tránsito y las reglas de parques nacionales y áreas protegidas. No extraer flora, fauna, fósiles ni patrimonio. Para conducir en rutas cordilleranas o zonas aisladas se recomienda revisar el clima, el estado del camino y llevar combustible y comunicación suficiente.', 'La moneda es el peso chileno. Las distancias y condiciones climáticas varían mucho entre regiones. Se recomienda contratar servicios registrados, cuidar pertenencias en zonas concurridas y contar con seguro médico. El número general de emergencias puede variar por servicio: 131 ambulancias, 132 bomberos y 133 Carabineros.', 'Para ingresar a Chile se requiere un documento de viaje vigente y, según la nacionalidad, visa o autorización previa. Se deben confirmar los requisitos migratorios, sanitarios y aduaneros en los canales oficiales. La entrada de alimentos, semillas, productos animales y vegetales está controlada y debe declararse.');
